CREATE TABLE bat_job_definition_version (
  job_id VARCHAR2(80) NOT NULL, definition_version NUMBER(19) NOT NULL, job_name VARCHAR2(200) NOT NULL,
  executor_type VARCHAR2(40) NOT NULL, definition_state VARCHAR2(20) NOT NULL, owner_domain VARCHAR2(80) NOT NULL,
  description VARCHAR2(1000), trigger_type VARCHAR2(30) NOT NULL, trigger_expression VARCHAR2(500), timezone_id VARCHAR2(60) NOT NULL,
  misfire_policy VARCHAR2(30) NOT NULL, agent_pool VARCHAR2(100) NOT NULL, zone_id VARCHAR2(80), max_concurrency NUMBER(10) NOT NULL,
  timeout_seconds NUMBER(19) NOT NULL, restartable_yn CHAR(1) NOT NULL, max_attempts NUMBER(10) NOT NULL, initial_backoff_seconds NUMBER(19) NOT NULL,
  backoff_multiplier NUMBER(10,4) NOT NULL, max_backoff_seconds NUMBER(19) NOT NULL, skip_limit NUMBER(10) NOT NULL,
  unknown_result_policy VARCHAR2(30) NOT NULL, compensation_reference VARCHAR2(200), alert_delay_seconds NUMBER(19) NOT NULL,
  sla_seconds NUMBER(19) NOT NULL, notify_failure_yn CHAR(1) NOT NULL, notify_missed_yn CHAR(1) NOT NULL,
  executor_reference VARCHAR2(300) NOT NULL, definition_json CLOB NOT NULL, checksum VARCHAR2(128), effective_from TIMESTAMP(3) NULL,
  effective_until TIMESTAMP(3) NULL, row_version NUMBER(19) NOT NULL, created_by VARCHAR2(100) NOT NULL, created_at TIMESTAMP(3) NOT NULL,
  updated_by VARCHAR2(100) NOT NULL, updated_at TIMESTAMP(3) NOT NULL,
  PRIMARY KEY(job_id,definition_version),
  CONSTRAINT ck_bat_job_def_state CHECK(definition_state IN ('DRAFT','VALIDATED','APPROVAL','PUBLISHED','RETIRED')),
  CONSTRAINT ck_bat_job_def_yesno CHECK(restartable_yn IN ('Y','N') AND notify_failure_yn IN ('Y','N') AND notify_missed_yn IN ('Y','N')),
  CONSTRAINT ck_bat_job_def_version CHECK(definition_version>0 AND row_version>0)
);
CREATE INDEX idx_bat_job_def_state ON bat_job_definition_version(definition_state,updated_at);
CREATE INDEX idx_bat_job_def_owner ON bat_job_definition_version(owner_domain,job_id);
CREATE TABLE bat_job_parameter_definition (
  job_id VARCHAR2(80) NOT NULL, definition_version NUMBER(19) NOT NULL, parameter_name VARCHAR2(100) NOT NULL,
  parameter_type VARCHAR2(40) NOT NULL, label_text VARCHAR2(200), description_text VARCHAR2(1000), required_yn CHAR(1) NOT NULL,
  sensitive_yn CHAR(1) NOT NULL, default_value VARCHAR2(1000), allowed_values CLOB, validation_pattern VARCHAR2(1000),
  min_value NUMBER(38,10), max_value NUMBER(38,10), min_length INT, max_length INT, reference_type VARCHAR2(80),
  alias_required_yn CHAR(1) NOT NULL, runtime_override_allowed_yn CHAR(1) NOT NULL, sort_order NUMBER(10) NOT NULL,
  PRIMARY KEY(job_id,definition_version,parameter_name),
  CONSTRAINT fk_bat_job_param_def FOREIGN KEY(job_id,definition_version) REFERENCES bat_job_definition_version(job_id,definition_version) ON DELETE CASCADE,
  CONSTRAINT ck_bat_job_param_yesno CHECK(required_yn IN ('Y','N') AND sensitive_yn IN ('Y','N') AND alias_required_yn IN ('Y','N') AND runtime_override_allowed_yn IN ('Y','N'))
);
CREATE TABLE bat_job_dependency (
  job_id VARCHAR2(80) NOT NULL, definition_version NUMBER(19) NOT NULL, related_job_id VARCHAR2(80) NOT NULL,
  condition_code VARCHAR2(40) NOT NULL, timeout_seconds NUMBER(19) NOT NULL, required_yn CHAR(1) NOT NULL, sort_order NUMBER(10) NOT NULL,
  PRIMARY KEY(job_id,definition_version,related_job_id),
  CONSTRAINT fk_bat_job_dep_def FOREIGN KEY(job_id,definition_version) REFERENCES bat_job_definition_version(job_id,definition_version) ON DELETE CASCADE,
  CONSTRAINT ck_bat_job_dep_self CHECK(job_id<>related_job_id), CONSTRAINT ck_bat_job_dep_yesno CHECK(required_yn IN ('Y','N'))
);
CREATE TABLE bat_job_definition_audit (
  audit_id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL, job_id VARCHAR2(80) NOT NULL, definition_version NUMBER(19) NOT NULL,
  action_code VARCHAR2(40) NOT NULL, from_state VARCHAR2(20), to_state VARCHAR2(20), reason VARCHAR2(1000) NOT NULL,
  operator_id VARCHAR2(100) NOT NULL, created_at TIMESTAMP(3) NOT NULL, PRIMARY KEY(audit_id)
);
CREATE INDEX idx_bat_job_def_audit ON bat_job_definition_audit(job_id,definition_version,created_at);
